-              nsIMsgFolder* arrived = m_copyState->m_arrFolder;
-              copyService->NotifyCompletion(m_copyState->m_srcSupport,
-                                            arrived ? arrived : this,
+              // NotifyCompletion() starts the next queued move which re-enters
